// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// dashboard (.open-next/worker.js, written by `opennextjs-cloudflare build`),
// wrapped by Sentry, plus the Cron Trigger that replaced the Vercel cron.
// See DEPLOY.md.
import * as Sentry from '@sentry/nextjs/cloudflare'
// Generated by the build, so it is missing before one (ts-expect-error would
// then fail after one).
// @ts-ignore
import openNext from '../.open-next/worker.js'
import { SENTRY_DATA_COLLECTION } from '../lib/sentry-data-collection'
import { createWorker, type FetchHandler, type WorkerEnv } from './handlers'

// Server errors and the snapshot's cron check-ins, as sentry.server.config.ts
// sets them up under `next start`. Inert until the SENTRY_DSN secret is set.
export default Sentry.withSentry(
  (env: WorkerEnv) => ({
    dsn: env.SENTRY_DSN,
    enabled: !!env.SENTRY_DSN,
    environment: env.APP_ENV,
    // Errors and cron check-ins only: no tracing.
    tracesSampleRate: 0,
    dataCollection: SENTRY_DATA_COLLECTION,
  }),
  createWorker(openNext as FetchHandler),
)
